<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,computed} from 'vue'
import {Download,LoaderCircle,Monitor,Laptop,Terminal,ShieldCheck,BookOpen,CheckCircle2,X,Copy} from 'lucide-vue-next'
import {useRoute} from 'vue-router'
import {accountApi} from '@/accountApi'
import {useAuthStore} from '@/stores/auth'
const route=useRoute(),auth=useAuthStore()
const emit=defineEmits<{(e:'open-billing'):void}>()
type Release={os:string;ready:boolean;version:string|null;sha256:string|null;download_url:string|null;channel?:string|null;architecture?:string|null;signing?:string|null}
const releases=ref<Release[]>([]),allowed=ref(false),loading=ref(true),error=ref(''),message=ref(''),busy=ref(''),accessBasis=ref<string|null>(null)
const progress=ref(0),total=ref(0),completed=ref(''),verified=ref(false),copied=ref(false)
let transfer:AbortController|null=null,disposed=false
const detected=typeof navigator==='undefined'?'':/Windows/i.test(navigator.userAgent)?'windows':/Macintosh|Mac OS/i.test(navigator.userAgent)?'macos':/Linux/i.test(navigator.userAgent)?'linux':''
const percent=computed(()=>total.value?Math.min(100,Math.floor(progress.value/total.value*100)):null)
const megabytes=(bytes:number)=>(bytes/1048576).toFixed(1)+' МБ'
const filenames:Record<string,string>={windows:'KINOSOTA-Player-Setup.exe',macos:'KINOSOTA-Player.dmg',linux:'kinosota-player.deb'}
const steps:Record<string,string>={windows:'Откройте KINOSOTA-Player-Setup.exe в загрузках браузера. В конце мастера оставьте включённым «Launch KINOSOTA Player» — плеер запустится после завершения установки.',macos:'Откройте KINOSOTA-Player.dmg, перенесите приложение в Applications, затем откройте его оттуда. DMG не запускает приложение автоматически после копирования.',linux:'Откройте kinosota-player.deb в системном менеджере приложений и подтвердите установку. Затем нажмите «Открыть», если эта кнопка доступна, или найдите KINOSOTA Player в меню приложений.'}
async function copyCommand(){try{await navigator.clipboard.writeText('sudo apt install ./kinosota-player.deb');copied.value=true}catch{message.value='Команда: sudo apt install ./kinosota-player.deb'}}
function cancelDownload(){transfer?.abort()}
onBeforeUnmount(()=>{disposed=true;transfer?.abort()})
const pairCode=ref(typeof route.query.player_code==='string'?route.query.player_code.toUpperCase():'')
const names:Record<string,string>={windows:'Windows',macos:'macOS',linux:'Linux'}
const profileTarget=computed(()=>'/profile?tab=player'+(pairCode.value?'&player_code='+encodeURIComponent(pairCode.value):''))
const platformHelp:Record<string,string>={windows:'Windows · x86_64 · установщик .exe',macos:'macOS · Apple Silicon (M1 и новее) · .dmg. Не для Intel Mac.',linux:'Linux · x86_64 · Debian 12 / Ubuntu 24.04 · .deb'}
async function load(){loading.value=true;error.value='';try{const data=await accountApi('/desktop/releases');releases.value=data.items;allowed.value=data.can_download;accessBasis.value=data.access_basis||null}catch{error.value='Не удалось проверить версии приложения. Повторите позже.'}finally{loading.value=false}}
async function download(item:Release){
 if(!item.download_url||busy.value||!['windows','macos','linux'].includes(item.os))return
 // Do not send an access token to a URL supplied by an untrusted release object.
 if(item.download_url!=='/api/v1/desktop/download/'+item.os){error.value='Некорректный адрес установщика.';return}
 busy.value=item.os;completed.value='';verified.value=false;progress.value=0;total.value=0;error.value='';transfer=new AbortController()
 try{
  const headers:Record<string,string>={};const token=localStorage.getItem('tg_stream_access_token');if(token&&token!=='cookie-session')headers.Authorization='Bearer '+token
  const response=await fetch(item.download_url,{headers,credentials:'same-origin',cache:'no-store',signal:transfer.signal})
  if(!response.ok){if(response.status===401)window.dispatchEvent(new CustomEvent('auth:expired'));throw new Error(response.status===401?'Сессия истекла. Войдите в аккаунт заново.':response.status===403?'Для скачивания нужна действующая платная подписка.':'Сборка пока недоступна. Повторите позже.')}
  total.value=Number(response.headers?.get('content-length'))||0
  if(total.value>536870912)throw new Error('Размер установщика превышает допустимый.')
  let blob:Blob
  if(response.body?.getReader){
   const reader=response.body.getReader();const chunks:BlobPart[]=[]
   while(true){const {done,value}=await reader.read();if(done)break;progress.value+=value.byteLength;if(progress.value>536870912){await reader.cancel();throw new Error('Размер установщика превышает допустимый.')}chunks.push(value)}
   blob=new Blob(chunks,{type:'application/octet-stream'})
  }else{blob=await response.blob();progress.value=blob.size}
  if(transfer.signal.aborted||disposed)return
  if(blob.size>536870912)throw new Error('Размер установщика превышает допустимый.')
  if(!blob.size)throw new Error('Получен пустой файл. Повторите скачивание.')
  if(item.sha256){
   if(!crypto.subtle)throw new Error('Браузер не поддерживает безопасную проверку файла. Откройте сайт в актуальном браузере.')
   const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()))).map(x=>x.toString(16).padStart(2,'0')).join('')
   if(digest!==item.sha256.toLowerCase())throw new Error('Контрольная сумма не совпала. Файл не сохранён — повторите скачивание.')
   verified.value=true
  }
  if(transfer.signal.aborted||disposed)return
  const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filenames[item.os];document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);completed.value=item.os
 }catch(e:any){if(!disposed)error.value=e.name==='AbortError'?'Скачивание отменено. Можно начать заново.':e.message||'Не удалось скачать приложение.'}finally{if(!disposed)busy.value='';transfer=null}
}
onMounted(load)
</script>
<template>
 <section id="desktop-player" class="desktop-player" aria-labelledby="desktop-player-title">
  <div class="download-hero">
   <div class="hero-copy"><header class="player-intro"><img src="/brand/icon-128.png" alt="" width="64" height="64"/><div><span class="privilege">{{accessBasis==='administrator'?'ДОСТУП АДМИНИСТРАТОРА':'ПРИВИЛЕГИЯ PRO'}}</span><h2 id="desktop-player-title">KINOSOTA Player</h2><p>Ваш кинотеатр на компьютере</p></div></header>
   <p v-if="accessBasis==='administrator'" class="admin-access" role="status">Все возможности плеера доступны вам как администратору. Покупать подписку не нужно.</p>
   <p class="lead">Ищите фильмы в каталоге и смотрите их в отдельном приложении. Плеер на базе mpv поддерживает больше форматов, чем браузер.</p>
   <div class="benefits"><span><Monitor :size="20" aria-hidden="true"/>Нативное приложение</span><span><ShieldCheck :size="20" aria-hidden="true"/>Защищённый вход</span></div></div>
  </div>
  <div class="download-heading"><Download :size="28" aria-hidden="true"/><div><h3>Установить на компьютер</h3><p class="notice">{{allowed?'Выберите вашу операционную систему.':'Установщики доступны с платной подпиской.'}}</p></div></div>
  <p v-if="loading" class="loading-release" role="status"><LoaderCircle class="spinner" :size="22" aria-hidden="true"/>Проверяем доступные версии…</p>
  <div v-else class="downloads">
   <article v-for="item in releases" :key="item.os" class="platform" :class="{'detected':detected===item.os}">
    <div class="platform-title"><component :is="item.os==='windows'?Monitor:item.os==='macos'?Laptop:Terminal" :size="34" aria-hidden="true"/><h4>{{names[item.os]}}</h4></div>
    <span v-if="detected===item.os" class="os-badge">Ваша ОС · проверьте архитектуру</span>
    <p class="notice">{{platformHelp[item.os]}}</p><p class="release-state">{{item.ready?(item.channel==='preview'?'Тестовая версия ':'Версия ')+item.version:'Сборка ещё не опубликована'}}</p>
    <p v-if="item.ready&&item.channel==='preview'&&item.os!=='linux'" class="notice security-note">Тестовая сборка без подписи издателя{{item.os==='macos'?' и notarization':''}}. Если ОС блокирует установку, не отключайте защиту.</p>
    <p v-if="item.os==='linux'&&item.ready" class="notice security-note">Локальный .deb может вызвать предупреждение о стороннем источнике. Устанавливайте только пакет с этого сайта; защита ОС остаётся включённой.</p>
    <button v-if="allowed&&item.ready" class="download-button" :aria-label="'Скачать установщик для '+names[item.os]" :disabled="!!busy" @click="download(item)"><LoaderCircle v-if="busy===item.os" class="spinner" :size="20" aria-hidden="true"/><Download v-else :size="20" aria-hidden="true"/>{{busy===item.os?'Скачиваем…':'Скачать установщик'}}<small v-if="!busy">{{item.os==='windows'?'.exe':item.os==='macos'?'.dmg':'.deb'}}</small></button>
    <span v-else>{{allowed?'Скачивание появится после публикации':'Доступно с платной подпиской'}}</span>
    <div v-if="busy===item.os" class="transfer" role="status" aria-live="polite"><div role="progressbar" aria-label="Загрузка установщика" :aria-valuenow="percent??undefined" :aria-valuemin="0" :aria-valuemax="100"><i :style="{width:percent===null?'30%':percent+'%'}" :class="{indeterminate:percent===null}"></i></div><span>{{megabytes(progress)}}<template v-if="total"> / {{megabytes(total)}} · {{percent}}%</template><template v-else> · загружаем файл</template></span><button class="secondary" type="button" @click="cancelDownload"><X :size="16" aria-hidden="true"/>Отменить</button></div>
   </article>
  </div>
  <div v-if="completed" class="download-complete" role="status"><CheckCircle2 :size="26" aria-hidden="true"/><div><h3>Файл передан в загрузки браузера</h3><p>{{verified?'SHA256 проверена. ':''}}Браузер может запросить место сохранения. После сохранения откройте файл в списке загрузок.</p><p>{{steps[completed]}}</p><p class="notice">Сайт не может автоматически запустить установщик или подтвердить его установку за вас.</p></div></div>
  <div class="player-guide" aria-label="Как начать смотреть"><h3><BookOpen :size="24" aria-hidden="true"/>Как пользоваться плеером</h3><ol><li><strong>Установите приложение</strong><span>Выберите вашу операционную систему и откройте скачанный установщик.</span></li><li><strong>Войдите в аккаунт</strong><span>В плеере введите логин и пароль от KINOSOTA. Или выберите «Войти через аккаунт в браузере» и подтвердите вход в открывшемся окне.</span></li><li><strong>Найдите фильм и смотрите</strong><span>Введите название в поиске плеера и откройте фильм.</span></li></ol></div>
  <div v-if="!loading&&!allowed" class="access-note"><strong>Скачивание и просмотр — с платной подпиской</strong><p>Информация о приложении доступна всем. Для скачивания и подключения нужен аккаунт с действующей платной подпиской.</p><router-link v-if="!auth.isAuthenticated.value" class="action" :to="{path:'/login',query:{redirect:profileTarget}}">Войти в аккаунт</router-link><button v-else-if="route.path==='/profile'" @click="emit('open-billing')">Открыть подписку и оплату</button><router-link v-else class="action" to="/profile?tab=billing">Открыть подписку и оплату</router-link></div>
  <p v-if="message" class="success" role="status">{{message}}</p><div v-if="error" class="error" role="alert">{{error}} <button type="button" @click="load">Повторить проверку версий</button></div>
  <details class="player-help"><summary>Совместимость, установка и удаление приложения</summary><p>Windows: x86_64. Удаление — «Параметры → Приложения → Установленные приложения» или «Настройки → О приложении → Удалить» в плеере. Запуск после интерактивной установки включён в мастере; это не автозагрузка при включении компьютера.</p><p>macOS: только Apple Silicon (M1 и новее), не Intel. Перенесите приложение в Applications и запустите вручную. Для удаления закройте его и переместите в Корзину. Предупреждения Gatekeeper не обходите.</p><p>Linux: x86_64, Debian 12 / Ubuntu 24.04 и совместимые системы. Откройте .deb в менеджере приложений. Удаление без терминала — «Настройки → О приложении → Удалить приложение» или действие «Удалить KINOSOTA Player» в меню значка. ОС запросит подтверждение. Видимость локальных .deb в App Center зависит от версии менеджера.</p><details><summary>Linux: дополнительный способ установки</summary><code>sudo apt install ./kinosota-player.deb</code><button v-if="allowed" type="button" class="secondary copy-command" @click="copyCommand"><Copy :size="16" aria-hidden="true"/>{{copied?'Скопировано':'Копировать команду'}}</button></details><p>Перед удалением выйдите из аккаунта в плеере, чтобы удалить сохранённую сессию. Удаление приложения не удаляет аккаунт на сайте. Поддержка кодеков зависит от mpv и доступности источника.</p></details>
 </section>
</template>
