:20px;display:flex;flex-direction:column;align-items:start;gap:10px}.platform h4{font-size:20px;margin:0}.platform p{margin:0}.platform span{font-size:14px;color:var(--ui-muted,#aebccc)}.platform code{font-size:12px;overflow-wrap:anywhere}.release-state{font-weight:600}.desktop-player button,.action{display:inline-flex;align-items:center;justify-content:center;min-height:44px;max-width:100%;border-radius:8px;padding:10px 16px;background:var(--ui-primary,#ffc400);color:var(--ui-on-primary,#141414);border:0;font:inherit;font-weight:700;cursor:pointer;text-decoration:none;white-space:normal;text-align:center}.desktop-player button:disabled{background:var(--ui-raised,#303b45);color:var(--ui-muted,#aeb7c1);cursor:default}.desktop-player button:focus-visible,.desktop-player a:focus-visible,.pairing input:focus-visible,.player-help summary:focus-visible{outline:2px solid var(--ui-link,#ffdb68);outline-offset:3px}.access-note p{margin:8px 0 16px}.download-heading p{margin:0}.player-help{border-top:1px solid var(--ui-border,#354150);padding-top:18px}.player-help summary{cursor:pointer;font-weight:600;min-height:44px;padding:8px 0}.success,.error{padding:16px;border-radius:8px;border:1px solid var(--ui-border,#45505d);margin:18px 0}.success{color:#a3e7c2}.error{color:#ffb8b8}.error button{margin:10px 0 0;display:flex}@container(max-width:820px){.player-guide ol{grid-template-columns:1fr;gap:16px}.downloads{grid-template-columns:1fr}.pair-controls{align-items:stretch;flex-direction:column}.pair-field{flex:auto;width:100%}.pair-controls button{width:100%}}@media(max-width:600px){.player-intro{gap:12px;align-items:flex-start}.player-intro img{width:52px;height:52px}.player-guide,.access-note,.pairing{padding:16px}.desktop-player{padding:18px}}

